/* JavaScript Node ACM模式 控制台输入获取 */
const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

const lines = [];
let n, m, matrix;
rl.on("line", (line) => {
  lines.push(line);

  if (lines.length === 1) {
    [n, m] = lines[0].split(" ").map(Number);
  }

  if (n && lines.length === n + 1) {
    lines.shift();
    matrix = lines.map((line) => line.split(" ").map(Number));
    getResult();
    lines.length = 0;
  }
});

function getResult() {
  // 广搜队列
  const queue = [];

  // 将（0，0）位置标记为“走过状态”，即将元素值设为2
  matrix[0][0] = 2;
  // 将走过的点加入队列
  queue.push(new Pos(0, 0, null));

  // 上下左右偏移
  const offsets = [
    [-1, 0],
    [1, 0],
    [0, -1],
    [0, 1],
  ];

  // 广搜
  while (queue.length > 0) {
    // 当前点
    const cur = queue.shift();

    // 遍历当前点的上、下、左、右方向的新点
    for (let [offsetX, offsetY] of offsets) {
      // 新点的坐标
      const newX = cur.x + offsetX;
      const newY = cur.y + offsetY;

      // 如果新点不越界，且未被访问过，且不是墙， 则新点可以访问
      if (
        newX >= 0 &&
        newX < n &&
        newY >= 0 &&
        newY < m &&
        matrix[newX][newY] == 0
      ) {
        // 将新点状态设为走过
        matrix[newX][newY] = 2;
        // 将新点和上一个点关联，形成路径链
        const next = new Pos(newX, newY, cur);
        queue.push(next);

        // 如果新点就是终点，那么则说明找到了起点到终点的路径
        if (newX == n - 1 && newY == m - 1) {
          // 打印路径
          printPath(next);
          // 结束查找
          return;
        }
      }
    }
  }
}

class Pos {
  constructor(x, y, pre) {
    this.x = x; // 当前点的横坐标
    this.y = y; // 当前点的纵坐标
    this.pre = pre; // 当前点的上一个点（此属性用于形成路径链）
  }
}

function printPath(cur) {
  // 这里采用递归打印，保证打印顺序是起点到终点
  if (cur.pre != null) {
    // 递归的作用是优先打印pre点，pre点打印完，回溯打印cur点
    printPath(cur.pre);
  }

  console.log(`(${cur.x},${cur.y})`);
}

