function dfs(x, y, path, ans) {
  // 如果当前点(x,y)就是终点(n-1, m-1)，则找到路径
  if (x == n - 1 && y == m - 1) {
    path.push([x, y]);
    // 将路径加入结果集ans中
    ans.push(...path);
    return true;
  }

  // 否则，向当前点上下左右四个方向继续深搜
  for (let [offsetX, offsetY] of offsets) {
    const newX = x + offsetX;
    const newY = y + offsetY;

    // 如果新点不越界，且未走过
    if (
      newX >= 0 &&
      newX < n &&
      newY >= 0 &&
      newY < m &&
      matrix[newX][newY] == 0
    ) {
      // 则加入路径
      path.push([x, y]);
      // 同时将新点标记为走过
      matrix[newX][newY] = 2;

      // 基于新点，继续深搜
      const res = dfs(newX, newY, path, ans);
      // 如果该分支可以到达终点，则结束深搜
      if (res) return true;

      // 回溯
      matrix[newX][newY] = 0;
      path.pop();
    }
  }
}

