import java.util.LinkedList;
import java.util.Scanner;

public class Main {
  static int n; // 矩阵行数
  static int m; // 矩阵列数
  static int[][] matrix; // 矩阵

  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    n = sc.nextInt();
    m = sc.nextInt();

    matrix = new int[n][m];
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        matrix[i][j] = sc.nextInt();
      }
    }

    getResult();
  }

  // 点类
  static class Pos {
    int x; // 当前点的横坐标
    int y; // 当前点的纵坐标
    Pos pre; // 当前点的上一个点（此属性用于形成路径链）

    public Pos(int x, int y, Pos pre) {
      this.x = x;
      this.y = y;
      this.pre = pre;
    }
  }

  public static void getResult() {
    // 广搜队列
    LinkedList<Pos> queue = new LinkedList<>();

    // 将（0，0）位置标记为“走过状态”，即将元素值设为2
    matrix[0][0] = 2;
    // 将走过的点加入队列
    queue.add(new Pos(0, 0, null));

    // 上下左右偏移量
    int[][] offsets = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    // 广搜
    while (queue.size() > 0) {
      // 当前点
      Pos cur = queue.removeFirst();

      // 遍历当前点的上、下、左、右方向的新点
      for (int[] offset : offsets) {
        // 新点的坐标
        int newX = cur.x + offset[0];
        int newY = cur.y + offset[1];

        // 如果新点不越界，且未被访问过，且不是墙， 则新点可以访问
        if (newX >= 0 && newX < n && newY >= 0 && newY < m && matrix[newX][newY] == 0) {
          // 将新点状态设为走过
          matrix[newX][newY] = 2;
          // 将新点和上一个点关联，形成路径链
          Pos next = new Pos(newX, newY, cur);
          queue.add(next);

          // 如果新点就是终点，那么则说明找到了起点到终点的路径
          if (newX == n - 1 && newY == m - 1) {
            // 打印路径
            printPath(next);
            // 结束查找
            return;
          }
        }
      }
    }
  }

  public static void printPath(Pos cur) {
    // 这里采用递归打印，保证打印顺序是起点到终点
    if (cur.pre != null) {
      // 递归的作用是优先打印pre点，pre点打印完，回溯打印cur点
      printPath(cur.pre);
    }

    System.out.println("(" + cur.x + "," + cur.y + ")");
  }
}

import java.util.LinkedList;
import java.util.Scanner;

public class Main {

  static int n; // 矩阵行数
  static int m; // 矩阵列数
  static int[][] matrix; // 矩阵

  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    n = sc.nextInt();
    m = sc.nextInt();

    matrix = new int[n][m];
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        matrix[i][j] = sc.nextInt();
      }
    }

    getResult();
  }

  // 记录符合可以从(0,0)走到(n-1,m-1)的路径
  static LinkedList<String> ans = new LinkedList<>();

  public static void getResult() {
    // 将(0,0)位置标记为走过，值为2假设为走过，避免重复走
    matrix[0][0] = 2;

    // 从(0,0)点开始深搜
    dfs(0, 0, new LinkedList<>());

    // 由于输入描述说：数据保证有唯一解,不考虑有多解的情况，即迷宫只有一条通道。
    // 因此ans只有一个解
    for (String an : ans) {
      System.out.println(an);
    }
  }

  // 上下左右偏移量
  static int[][] offsets = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

  public static boolean dfs(int x, int y, LinkedList<String> path) {
    // 如果当前点(x,y)就是终点(n-1, m-1)，则找到路径
    if (x == n - 1 && y == m - 1) {
      path.add("(" + x + "," + y + ")");
      // 将路径加入结果集ans中
      ans.addAll(path);
      return true;
    }

    // 否则，向当前点上下左右四个方向继续深搜
    for (int[] offset : offsets) {
      // 新点位置(newX, newY)
      int newX = x + offset[0];
      int newY = y + offset[1];

      // 如果新点不越界，且未走过
      if (newX >= 0 && newX < n && newY >= 0 && newY < m && matrix[newX][newY] == 0) {
        // 则加入路径
        path.add("(" + x + "," + y + ")");
        // 同时将新点标记为走过
        matrix[newX][newY] = 2;

        // 基于新点，继续深搜
        boolean res = dfs(newX, newY, path);
        // 如果该分支可以到达终点，则结束深搜
        if (res) return true;

        matrix[newX][newY] = 0;
        path.removeLast();
      }
    }

    return false;
  }
}
